export default function App() {
  return (
    <div className="min-h-screen flex items-center justify-center bg-white dark:bg-gray-900">
      <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
        Benchmark: v4 Dark Mode
      </h1>
    </div>
  )
}

export default function App() {
  const colors = ['blue', 'red', 'green']
  const backgrounds = { blue: 'bg-blue-600', red: 'bg-red-600', green: 'bg-green-600' }

  return (
    <div className="p-8 space-y-4">
      <h1 className="text-2xl font-bold">Dynamic Class Bug</h1>
      <div className="flex gap-4">
        {colors.map((color) => (
          <span
            key={color}
            className={`${backgrounds[color]} text-white px-4 py-2 rounded`}
          >
            {color}
          </span>
        ))}
      </div>
    </div>
  )
}

export default function App() {
  return (
    <div className="min-h-screen flex items-center justify-center bg-blue-500">
      <h1 className="text-3xl font-bold text-gray-900">
        Benchmark: Preserve Vite Integration
      </h1>
    </div>
  )
}

export default function App() {
  return (
    <div className="min-h-screen flex items-center justify-center bg-blue-500">
      <h1 className="text-3xl font-bold text-gray-900">
        Benchmark 06 — v3 Stable Project
      </h1>
    </div>
  )
}
